        "answer": "独立三帧有符号误差为+2、0、-1，绝对误差2、0、1，MAE=1只/帧，计算(2+0+1)/3=1，预测为模拟给定。原四帧MAE=(1+1+1+2)/4=1.25，先求有符号和所得-0.25不能叫MAE。Z绝对误差1，相对误差因分母0未定义，记不适用。",
