          "分母应当与分子来自同一批有效配对帧，缺少预测的帧不能偷偷填零，也不能只增加分母。另列缺失是为了让人看见覆盖不足，排除后算出的数字只描述已配对部分，不能把较小的均值解释成整段输入已经都测过。",
