        "answer": "# 教学模拟；预期输出，未运行。\n# 第二组等于门槛，>误返回False；return交回结果，print只显示。\ndef keep_score(score, threshold):\n    return score >= threshold\n\ndef strict_score(score, threshold):\n    return score > threshold\n\ncases = [(0.7, 0.5), (0.5, 0.5), (0.4, 0.5)]\ncorrect = [keep_score(score, threshold) for score, threshold in cases]\nstrict = [strict_score(score, threshold) for score, threshold in cases]\nassert correct == [True, True, False]\nassert strict == [True, False, False]\nassert all(type(value) is bool for value in correct)\nprint(f\"contract={correct}\")\nprint(f\"strict={strict}\")\n# 预期输出：\n# contract=[True, True, False]\n# strict=[True, False, False]\n\n# 新独立FUNC-X，门槛随调用改变。\ncases_x = [(0.2, 0.2), (0.6, 0.7), (0.95, 0.9)]\ncorrect_x = [keep_score(s, t) for s, t in cases_x]\nstrict_x = [strict_score(s, t) for s, t in cases_x]\nassert correct_x == [True, False, True]\nassert strict_x == [False, False, True]\nprint(f\"contractX={correct_x}\")\nprint(f\"strictX={strict_x}\")\n",
